import{_ as a,o,c as r,a3 as n}from"./chunks/framework.DMtjdCb-.js";const e="/help/assets/continue-watching.ja.BiPoXp-Y.png",i="/help/assets/potplayer-weekly.ja.BtErWIRR.png",l="/help/assets/viewing-record.ja.D4n54Nl_.png",m=JSON.parse('{"title":"6. まとめて続きを再生","description":"","frontmatter":{},"headers":[],"relativePath":"ja/continue-watching.md","filePath":"ja/continue-watching.md"}'),s={name:"ja/continue-watching.md"};function p(c,t,g,h,_,d){return o(),r("div",null,[...t[0]||(t[0]=[n('<h1 id="_6-まとめて続きを再生" tabindex="-1">6. まとめて続きを再生 <a class="header-anchor" href="#_6-まとめて続きを再生" aria-label="Permalink to &quot;6. まとめて続きを再生&quot;">​</a></h1><p>購読中の TV アニメのうち、新着の未視聴分がある作品を一つのリストにまとめます。各作品は保存した再開話数を含めて、その時点で再生できる最新話まで並びます。</p><h2 id="今回見るリストを作る" tabindex="-1">今回見るリストを作る <a class="header-anchor" href="#今回見るリストを作る" aria-label="Permalink to &quot;今回見るリストを作る&quot;">​</a></h2><ol><li><strong>新作レーダー</strong> で対象シーズンを選びます。</li><li><strong>まとめて続きを再生</strong> を押し、話数一覧を待ちます。</li><li>今回見る作品にチェックを入れます。最初は未選択で、1 作品以上選ぶと再生ボタンが有効になります。</li><li>行頭のハンドルをドラッグして順序を変更します。必要なら開始・終了話数も調整します。</li><li>プレーヤーを選びます。チェックした作品だけが、上から順にリストへ入ります。</li></ol><p><img src="'+e+'" alt="まとめ再生：作品を選択し、ドラッグで並べ替える" loading="lazy"></p><p><strong>確認する状態：</strong> プレーヤーのリストに、選択した作品と話数が指定順で並びます。</p><p><img src="'+i+'" alt="PotPlayer のサイドバー：複数作品を連続再生" loading="lazy"></p><p>例えば A が第 3 話から再開して第 4 話まで、B が第 4 話から再開して第 5 話まで再生できる場合、A を先に置くと A 第 3–4 話、B 第 4–5 話の順になります。次回は実際に取得した視聴記録から再計算します。</p><h2 id="薄緑色の意味" tabindex="-1">薄緑色の意味 <a class="header-anchor" href="#薄緑色の意味" aria-label="Permalink to &quot;薄緑色の意味&quot;">​</a></h2><p>薄緑色は、<strong>購読中で最新話がまだ視聴完了になっていない作品</strong>を示します。詳細を開くだけ、または再開話数を最新話と同じにするだけでは消えません。</p><p>次のいずれかで、現在の最新話を視聴済みと判断します。</p><ul><li><strong>最新話を視聴済みにする</strong> を押す。</li><li>現在の最新話より大きい再開話数を保存する。</li><li>PotPlayer 拡張から、最新話の <strong>90%</strong> 以上を再生した記録を受け取る。</li></ul><p>新しい話が出ると再び判定します。購読の一時停止・解除・非表示の作品は新規リストに含めませんが、記録は保存されます。</p><h2 id="correct" tabindex="-1">視聴記録を修正する <a class="header-anchor" href="#correct" aria-label="Permalink to &quot;視聴記録を修正する {#correct}&quot;">​</a></h2><ol><li>レーダーの視聴話数の数字、または作品詳細の視聴記録を開きます。</li><li>次回の開始話数を入力し、必要に応じて位置も指定します。</li><li><strong>保存</strong> します。レーダーと以降のリストに反映されます。</li></ol><p><img src="'+l+'" alt="視聴記録：保存、最初から視聴、最新話の完了" loading="lazy"></p><p><strong>最初から視聴</strong> は再開状態をリセットします。<strong>最新話を視聴済みにする</strong> は完了を明示します。誤って変更した場合は同じウィンドウの <strong>元に戻す</strong> で直前の記録へ戻せます。</p><p>リストを作成しただけで全話を視聴済みにはしません。アクセスによる推定は先読みの影響を受けるため、正確な拡張のフィードバックがある方が確実です。</p>',18)])])}const P=a(s,[["render",p]]);export{m as __pageData,P as default};
